import { ReactNode } from 'react';
import { Accept, DropzoneProps, FileRejection, FileWithPath } from 'react-dropzone';
import { CommonProps } from '../../utility/commonProps';
export type FileUploadSize = 'small' | 'large';
export interface IFileUploadProps extends CommonProps, Omit<DropzoneProps, 'children'> {
    /**
     * The size of the file upload component.
     * @default 'small'
     */
    size?: FileUploadSize;
    /**
     * Optional custom text to display inside the dropzone.
     */
    dropzoneText?: ReactNode;
    /**
     * File types to accept
     * @default {
     *   'application/vnd.ms-excel': ['.csv', '.xlsx'],
     *   'application/pdf': ['.pdf'],
     *   'image/*': ['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.webp'],
     *   'video/*': ['.mp4', '.avi', '.mov', '.wmv', '.flv', '.webm']
     * }
     */
    acceptedFileTypes?: Accept;
    /**
     * Maximum file size in bytes
     * @default 500000 (500KB)
     */
    maxSize?: number;
    /**
     * Maximum total size of all files in bytes
     * @default 500000 (500KB)
     */
    maxTotalSize?: number;
    /**
     * Custom class name for the dropzone area
     */
    dropzoneClassName?: string;
    /**
     * Whether only one file can be uploaded at a time
     * @default true
     */
    singleFile?: boolean;
    /**
     * Custom text to show for downloading template
     */
    templateText?: string;
    /**
     * URL for downloading template file
     */
    templateUrl?: string;
    /**
     * Callback when template link is clicked
     */
    onTemplateClick?: () => void;
    /**
     * Whether the component is in a disabled state
     * @default false
     */
    disabled?: boolean;
    /**
     * Files currently being processed with progress indicator
     */
    filesWithProgress?: Array<{
        file: FileWithPath;
        progress: number;
    }>;
    /**
     * Controlled accepted files list
     */
    acceptedFiles?: FileWithPath[];
    /**
     * Controlled rejected files list
     */
    rejectedFiles?: FileRejection[];
    /**
     * Callback when a file delete action is triggered
     */
    onFileDelete?: (file: FileWithPath, index: number) => void;
    /**
     * Callback when a rejected file delete action is triggered
     */
    onRejectedFileDelete?: (file: FileRejection, index: number) => void;
    /**
     * Callback when a file upload in progress is cancelled
     */
    onProgressCancel?: (file: FileWithPath, index: number) => void;
}
